import 'package:cloud_firestore/cloud_firestore.dart';import 'package:flutter/material.dart';class BannersAdminPage extends StatelessWidget{const BannersAdminPage({super.key});@override Widget build(BuildContext c){final title=TextEditingController(),image=TextEditingController();return Scaffold(appBar:AppBar(title:const Text('Banner Promo')),floatingActionButton:FloatingActionButton(onPressed:()=>showDialog(context:c,builder:(d)=>AlertDialog(title:const Text('Banner baru'),content:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:title,decoration:const InputDecoration(labelText:'Judul')),TextField(controller:image,decoration:const InputDecoration(labelText:'URL gambar banner'))]),actions:[TextButton(onPressed:()=>Navigator.pop(d),child:const Text('Batal')),FilledButton(onPressed:()async{await FirebaseFirestore.instance.collection('banners').add({'title':title.text,'imageUrl':image.text,'active':true,'createdAt':FieldValue.serverTimestamp()});if(d.mounted)Navigator.pop(d);},child:const Text('Simpan'))])),child:const Icon(Icons.add)),body:StreamBuilder<QuerySnapshot<Map<String,dynamic>>>(stream:FirebaseFirestore.instance.collection('banners').orderBy('createdAt',descending:true).snapshots(),builder:(c,s){if(!s.hasData)return const Center(child:CircularProgressIndicator());return ListView(children:s.data!.docs.map((d){final x=d.data();return Card(child:ListTile(leading:x['imageUrl']?.toString().isNotEmpty==true?Image.network(x['imageUrl'],width:60,fit:BoxFit.cover):const Icon(Icons.image),title:Text(x['title']??'Banner'),trailing:Switch(value:x['active']??true,onChanged:(v)=>d.reference.update({'active':v})));}).toList());}));}}